import sys

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    N = int(input_data[idx]); idx += 1
    K = int(input_data[idx]); idx += 1

    requests = []
    for i in range(N):
        requests.append(int(input_data[idx])); idx += 1

    center = (K + 1) // 2

    seats = [[False] * (K + 1) for _ in range(K + 1)]

    results = []

    for M in requests:
        best = None
        best_dist = None
        best_row = None
        best_yl = None

        for row in range(1, K + 1):
            row_dist = (row - center) ** 2

            for yl in range(1, K - M + 2):
                yr = yl + M - 1

                all_free = True
                for s in range(yl, yr + 1):
                    if seats[row][s]:
                        all_free = False
                        break

                if not all_free:
                    continue

                seat_dist = 0
                for s in range(yl, yr + 1):
                    seat_dist += (s - center) ** 2
                total_dist = row_dist * M + seat_dist

                better = False
                if best_dist is None:
                    better = True
                elif total_dist < best_dist:
                    better = True
                elif total_dist == best_dist:
                    if row < best_row:
                        better = True
                    elif row == best_row and yl < best_yl:
                        better = True

                if better:
                    best_dist = total_dist
                    best_row = row
                    best_yl = yl
                    best = (row, yl, yr)

        if best is None:
            results.append("-1")
        else:
            row, yl, yr = best
            for s in range(yl, yr + 1):
                seats[row][s] = True
            results.append(f"{row} {yl} {yr}")

    print('\n'.join(results))

solve()

