import sys

def solve():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    out_lines = []
    while True:
        try:
            N = int(next(it))
            M = int(next(it))
        except StopIteration:
            break
        adj = [[] for _ in range(N)]
        for _ in range(M):
            u = int(next(it)) - 1
            v = int(next(it)) - 1
            adj[u].append(v)
            adj[v].append(u)
        visited = [False]*N
        components = 0
        stack = []
        for i in range(N):
            if not visited[i]:
                components += 1
                stack.append(i)
                visited[i] = True
                while stack:
                    node = stack.pop()
                    for nb in adj[node]:
                        if not visited[nb]:
                            visited[nb] = True
                            stack.append(nb)
        answer = M - N + components
        out_lines.append(str(answer))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

