import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    a = data[1:1+n]
    MOD = 10**9+7
    BITS = 20
    M = 1 << BITS
    cnt = [0]*M
    for x in a:
        cnt[int(x)] += 1
    # superset sum: f[mask] = number of elements that have all bits of mask set
    for i in range(BITS):
        bit = 1 << i
        for mask in range(M):
            if mask & bit == 0:
                cnt[mask] += cnt[mask | bit]
    pow2 = [1]*(n+1)
    for i in range(1, n+1):
        pow2[i] = pow2[i-1]*2 % MOD
    ans = 0
    for mask in range(M):
        c = cnt[mask]
        term = (pow2[c]-1) % MOD
        if bin(mask).count("1") & 1:
            ans = (ans - term) % MOD
        else:
            ans = (ans + term) % MOD
    print(ans % MOD)

