import sys

def minimal_number(s: str) -> str:
    if s == "0":
        return "0"
    digits = sorted(s)
    if digits[0] != '0':
        return ''.join(digits)
    # find first non-zero
    for i, d in enumerate(digits):
        if d != '0':
            # place this digit first, then all zeros, then rest
            first = d
            zeros = digits[:i]
            rest = digits[i+1:]
            return first + ''.join(zeros) + ''.join(rest)
    return ''.join(digits)  # all zeros, shouldn't happen except "0"

