import sys

def process_dataset(n, moves):
    left = 0
    right = 0
    count = 0
    last_full = 0  # last uniform state both feet were on
    valid = True   # whether current transition has been valid

    for mv in moves:
        if mv == 'lu':
            if left == 1:
                valid = False
                continue
            left = 1
        elif mv == 'ru':
            if right == 1:
                valid = False
                continue
            right = 1
        elif mv == 'ld':
            if left == 0:
                valid = False
                continue
            left = 0
        elif mv == 'rd':
            if right == 0:
                valid = False
                continue
            right = 0

        if left == right:
            # reached a uniform state
            if left != last_full and valid:
                count += 1
            last_full = left
            valid = True
        # else intermediate, keep valid as is

    return count

def main():
    data = sys.stdin.read().strip().split()
    idx = 0
    out_lines = []
    while idx < len(data):
        n = int(data[idx])
        idx += 1
        if n == 0:
            break
        moves = data[idx:idx+n]
        idx += n
        out_lines.append(str(process_dataset(n, moves)))
