import sys

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    results = []
    while True:
        N = int(input_data[idx]); M = int(input_data[idx+1])
        idx += 2
        if N == 0 and M == 0:
            break
        codebook = []
        for i in range(M):
            codebook.append(int(input_data[idx])); idx += 1
        x = []
        for i in range(N):
            x.append(int(input_data[idx])); idx += 1

        INF = float('inf')
        # dp[v] = min sum of squared error to be at value v
        dp = [INF] * 256
        dp[128] = 0

        for n in range(N):
            ndp = [INF] * 256
            for v in range(256):
                if dp[v] == INF:
                    continue
                for c in codebook:
                    nv = v + c
                    if nv < 0:
                        nv = 0
                    elif nv > 255:
                        nv = 255
                    cost = dp[v] + (nv - x[n]) ** 2
                    if cost < ndp[nv]:
                        ndp[nv] = cost
            dp = ndp

        results.append(min(dp))

    print('\n'.join(map(str, results)))

main()

