import sys

ALLOWED = list("()+*-+&^|0123456789")
OPS = set("*+-&^|")
PRECEDENCE = {
    '*': 0,
    '+': 1, '-': 1,
    '&': 2,
    '^': 3,
    '|': 4
}

def tokenize(s):
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            yield s[i:j]
            i = j
        else:
            yield c
            i += 1

def parse_number(tok):
    if not tok.isdigit():
        return None
    if tok[0] == '0':
        return None
    return int(tok)

def parse_expr(tokens, min_prec=0):
    # left-associative Pratt parser
    def next_token():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def consume():
        pos[0] += 1

    pos = [0]
    # parse primary
    t = next_token()
    if t is None:
        raise ValueError
    if t == '(':
        consume()
        left = parse_expr(tokens, 0)
        if next_token() != ')':
            raise ValueError
        consume()
    else:
        val = parse_number(t)
        if val is None:
            raise ValueError
        left = val
        consume()

    while True:
        op = next_token()
        if op not in OPS:
            break
        prec = PRECEDENCE[op]
        if prec < min_prec:
            break
        consume()
        # left-assoc: next min_prec = prec+1
        right = parse_expr(tokens, prec + 1)
        if op == '*':
            left = left * right
        elif op == '+':
            left = left + right
        elif op == '-':
            left = left - right
        elif op == '&':
            left = left & right
        elif op == '^':
            left = left ^ right
        elif op == '|':
            left = left | right
    return left

def evaluate(s):
    toks = list(tokenize(s))
    return parse_expr(toks, 0)

def is_valid(s):
    if not s:
        return False
    try:
        val = evaluate(s)
    except Exception:
        return False
    return True

from functools import lru_cache

def generate_moves(s):
    res = set()
    L = len(s)
    # deletions
    for i in range(L):
        ns = s[:i] + s[i+1:]
        if ns and is_valid(ns):
            res.add(ns)
    # insertions
    for i in range(L+1):
        for ch in ALLOWED:
            ns = s[:i] + ch + s[i:]
            if is_valid(ns):
                res.add(ns)
    return res

@lru_cache(None)
def solve_state(s, moves_left, turn):
    if moves_left == 0:
        return evaluate(s)
    moves = generate_moves(s)
    if not moves:
        return evaluate(s)
    if turn == 0:  # maximizer
        best = -10**18
        for ns in moves:
            val = solve_state(ns, moves_left-1, 1)
            if val > best:
                best = val
        return best
    else:  # minimizer
        best = 10**18
        for ns in moves:
            val = solve_state(ns, moves_left-1, 0)
            if val < best:
                best = val
        return best

def main():
    out = []
    for line in sys.stdin:
        line=line.rstrip('\n')
        if not line:
            continue
        if line.startswith('0'):
            break
        parts=line.split(' ',1)
        N=int(parts[0])
        expr=parts[1].replace(' ','')
        out.append(str(solve_state(expr,N,0)))
    sys.stdout.write('\n'.join(out))

if __name__=="__main__":
    main()

