import sys

def reverse_one(strings, L):
    prev = chr(ord(L) - 1)
    new_set = set()
    for s in strings:
        new_set.add(s)
        i = s.find(prev)
        if i != -1:
            if L not in s[:i]:
                lst = list(s)
                lst[i] = L
                new_set.add(''.join(lst))
    return new_set

def encrypt(s):
    s = list(s)
    for code in range(ord('b'), ord('z') + 1):
        L = chr(code)
        prev = chr(code - 1)
        for i in range(len(s)):
            if s[i] == L:
                s[i] = prev
                break
    return ''.join(s)

def candidates(encrypted):
    cur_set = {encrypted}
    for code in range(ord('z'), ord('b') - 1, -1):
        L = chr(code)
        cur_set = reverse_one(cur_set, L)
    valid = [s for s in cur_set if encrypt(s) == encrypted]
