import sys
from datetime import date

def main():
    era_offsets = {
        'MEIJI': 1867,
        'TAISHO': 1911,
        'SHOWA': 1925,
        'HEISEI': 1988,
    }
    era_order = ['MEIJI', 'TAISHO', 'SHOWA', 'HEISEI', '?']

    starts = {
        'MEIJI': date(1868, 1, 25),
        'TAISHO': date(1912, 7, 30),
        'SHOWA': date(1926, 12, 25),
        'HEISEI': date(1989, 1, 8),
        '?': date(2019, 5, 1),
    }

    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line or line == '#':
            break
        parts = line.split()
        if len(parts) != 4:
            continue
        g, y, m, d = parts[0], int(parts[1]), int(parts[2]), int(parts[3])

        if g not in era_offsets:
            continue

        offset = era_offsets[g]
        gy = offset + y

        try:
            cur = date(gy, m, d)
        except ValueError:
            continue

        # Determine target era based on Gregorian date
        if cur >= starts['?']:
            target = '?'
        elif cur >= starts['HEISEI']:
            target = 'HEISEI'
        elif cur >= starts['SHOWA']:
            target = 'SHOWA'
        elif cur >= starts['TAISHO']:
            target = 'TAISHO'
        else:
            target = 'MEIJI'

        # The actual era can only be the same or later than the stored era.
        # If computation yields an earlier era, keep the stored era.
        if era_order.index(target) < era_order.index(g):
            target = g

        if target == '?':
            year = gy - 2019 + 1
            out.append(f"? {year} {m} {d}")
        else:
            year = gy - era_offsets[target]
            out.append(f"{target} {year} {m} {d}")

    print("\n".join(out))

if __name__ == "__main__":
    main()

