import sys, math

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    X = int(data[0])
    best_a = 1
    best_b = X
    limit = int(math.isqrt(X))
    for d in range(1, limit + 1):
        if X % d == 0:
            e = X // d
            if math.gcd(d, e) == 1:
                best_a, best_b = d, e
    print(best_a, best_b)

if __name__ == "__main__":
    solve()
